{
  "root_causes": [
    {
      "service": "ts-route-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT src, span_name, attr_span_kind, count(*) n, round(approx_quantile(duration,0.5)/1e6,2) p50_ms, round(approx_quantile(duration,0.95)/1e6,2) p95_ms FROM (SELECT 'nor' src, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) WHERE service_name='ts-route-service' AND span_name LIKE 'SELECT ts.route%' GROUP BY 1,2,3 ORDER BY 2,1", "claim": "Route-service DB spans (SELECT ts.route_stations / route_distances) rose from ~0.1 ms p95 to ~440-510 ms p95 in the incident."},
        {"kind": "trace", "sql": "SELECT src, span_name, count(*) n, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM (SELECT 'nor' src, * FROM normal_traces UNION ALL SELECT 'abn', * FROM abnormal_traces) WHERE service_name='ts-route-service' AND span_name IN ('SELECT route.entity.Route','RouteRepository.findAll','RouteController.queryAll') GROUP BY 1,2 ORDER BY 2,1", "claim": "Route entity lookups and route queries in route-service slowed from ~3 ms to hundreds of ms or more, inside the process's DB layer."},
        {"kind": "metric", "sql": "SELECT 'abn' src, service_name, metric, round(avg(value),3) avg_v FROM abnormal_metrics WHERE service_name='ts-route-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu.usage') GROUP BY 1,2,3 UNION ALL SELECT 'nor', service_name, metric, round(avg(value),3) FROM normal_metrics WHERE service_name='ts-route-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu.usage') GROUP BY 1,2,3", "claim": "Route-service CPU fell during the incident, so the slowdown is not CPU saturation; mysql CPU also fell."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-route-service", "to": "ts-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(approx_quantile(p.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE p.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-travel-service' AND p.service_name='ts-route-service' GROUP BY 1,2", "claim": "Calls from ts-travel-service to ts-route-service show callee server p95 around 1 second in the incident."}]},
    {"from": "ts-travel-service", "to": "ts-admin-travel-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(approx_quantile(p.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE p.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-admin-travel-service' AND p.service_name='ts-travel-service' GROUP BY 1,2", "claim": "ts-admin-travel-service calls to ts-travel-service have server p95 around 5.9 seconds."}]},
    {"from": "ts-admin-travel-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(approx_quantile(p.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE p.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-ui-dashboard' AND p.service_name IN ('ts-admin-travel-service','ts-admin-route-service','ts-route-service') GROUP BY 1,2", "claim": "ts-ui-dashboard calls to admin-travel, admin-route and route services show multi-second to 50-second p95 latency."}]},
    {"from": "ts-route-service", "to": "ts-admin-route-service", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(approx_quantile(p.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE p.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-admin-route-service' AND p.service_name='ts-route-service' GROUP BY 1,2", "claim": "ts-admin-route-service calls to ts-route-service have server p95 of tens of seconds in the incident."}]},
    {"from": "ts-route-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT c.service_name caller, p.service_name callee, count(*) n, round(approx_quantile(p.duration,0.95)/1e6,1) callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.trace_id=p.trace_id AND c.span_id=p.parent_span_id WHERE p.attr_span_kind='Server' AND c.attr_span_kind='Client' AND c.service_name='ts-ui-dashboard' AND p.service_name='ts-route-service' GROUP BY 1,2", "claim": "ts-ui-dashboard calls to ts-route-service reach tens of seconds p95, the user-facing degradation."}]}
  ]
}
